/**
 * Local Express wrapper for testing Lambda against local Hardhat chains.
 *
 * Usage:
 *   1. Deploy contracts locally: cd contracts && npx hardhat run scripts/deploy-local.ts --network localhost
 *   2. Start this server: node local-server.mjs
 *   3. POST to http://localhost:3001 with mint requests
 */

import express from 'express';
import cors from 'cors';
import dotenv from 'dotenv';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
// .env.local (auto-generated by deploy-local.ts) takes priority over .env
dotenv.config({ path: resolve(__dirname, '../.env.local') });
dotenv.config({ path: resolve(__dirname, '../.env') });

// Force local mode
process.env.LOCAL_MODE = 'true';

// Mock prices for local testing
process.env.MOCK_ETH_PRICE = process.env.MOCK_ETH_PRICE || '3000';
process.env.MOCK_FLR_PRICE = process.env.MOCK_FLR_PRICE || '0.02';
process.env.MOCK_BNB_PRICE = process.env.MOCK_BNB_PRICE || '600';

const { handler } = await import('./index.mjs');

const app = express();
app.use(cors());
app.use(express.json());

app.post('/', async (req, res) => {
    try {
        const event = {
            body: JSON.stringify(req.body),
            headers: req.headers,
            httpMethod: 'POST'
        };

        const result = await handler(event);

        res.status(result.statusCode)
           .set(result.headers)
           .json(JSON.parse(result.body));
    } catch (error) {
        console.error('Local server error:', error);
        res.status(500).json({ error: error.message });
    }
});

app.options('/', (req, res) => {
    res.set(CORS_HEADERS).status(200).end();
});

const PORT = process.env.LAMBDA_LOCAL_PORT || 3001;
app.listen(PORT, () => {
    console.log(`\nLambda local server: http://localhost:${PORT}`);
    console.log(`ETH RPC:  ${process.env.ETH_RPC_URL || 'not set'}`);
    console.log(`Flare RPC: ${process.env.FLARE_RPC_URL || 'not set'}`);
    console.log(`BSC RPC:  ${process.env.BSC_RPC_URL || 'not set'}`);
    console.log(`Signer:   ${process.env.SIGNER_PRIVATE_KEY ? 'loaded' : 'NOT SET'}`);
    console.log('');
});
